"""Official DP/DP3 numerical oracle and raw train-only observation contracts."""

import copy
import json
import shutil

import numpy as np
import pytest
import torch

from test_m5 import compute_budget, config, dataset, episode
from test_minadit_v5 import add_commands
from feedingrobot.policies.corpus import TrainingWindows
from feedingrobot.policies.data import ActionWindows
from feedingrobot.policies.dp_normalizer import check_dp_limits, fit_dp_limits, fit_linear_limits, linear_transform
from feedingrobot.policies.normalization import denormalize_actions, normalize_actions


# Generated by the unmodified _fit/_normalize in BOTH pinned official sources:
# DP 5ba07ac6661db573af695b419a7947ecb704690f;
# DP3 47385d9d6f5bde3f2ebdf2400ecb8261cc9e6b97. No network needed at test time.
ORACLE_INPUT = np.array([[2., -4., 1., .01, -.06, -1e-4],
                         [6., 8., 1., .01005, .08, 0.],
                         [4., 2., 1., .010025, .02, -5e-5]])
ORACLE_PARAMS = dict(
    scale=[.5, .1666666716337204, 1., 1., 14.285714149475098, 20000.],
    offset=[-2., -.3333333134651184, -1., -.009999999776482582, -.14285719394683838, 1.],
    input_stats=dict(
        min=[2., -4., 1., .009999999776482582, -.05999999865889549, -9.999999747378752e-5],
        max=[6., 8., 1., .010049999691545963, .07999999821186066, 0.],
        mean=[4., 2., 1., .01002500019967556, .013333332724869251, -4.999999873689376e-5],
        std=[2., 6., 0., 2.4999957531690598e-5, .07023768872022629, 4.999999873689376e-5]))
ORACLE_OUTPUT = np.array([[-1., -1., 0., 0., -1., -1.],
                          [1., 1., 0., 4.9999915063381195e-5, .9999998807907104, 1.],
                          [0., 2.9802322387695312e-8, 0., 2.5000423192977905e-5, .14285707473754883, 0.]],
                         dtype=np.float32)


def test_dp_fit_exact_official_fp32_stats_constants_and_threshold():
    assert fit_linear_limits(ORACLE_INPUT) == ORACLE_PARAMS
    # The channel whose FP32 range equals FP32 1e-4 is scaled; '<' is strict.
    assert ORACLE_PARAMS['scale'][-1] == 20000.
    with pytest.raises(ValueError, match='finite valid'):
        fit_linear_limits(np.full((2, 6), np.nan))


@pytest.mark.parametrize('tensor', [False, True])
def test_dp_forward_matches_official_shape_dtype_inverse_and_no_clipping(tensor):
    values = np.stack([ORACLE_INPUT, ORACLE_INPUT])
    values = torch.as_tensor(values, dtype=torch.float64) if tensor else values
    normalization = dict(kind='dp_limits', params_dict=dict(action=ORACLE_PARAMS))
    actual = normalize_actions(values, normalization)
    assert actual.shape == values.shape
    assert actual.dtype == (torch.float32 if tensor else np.float32)
    np.testing.assert_array_equal(np.asarray(actual), np.stack([ORACLE_OUTPUT, ORACLE_OUTPUT]))
    decoded = denormalize_actions(actual, normalization)
    np.testing.assert_allclose(np.asarray(decoded), np.asarray(values), rtol=1e-6, atol=1e-7)
    outside = np.array([[100.] * 6])
    assert (normalize_actions(outside, normalization) > 1).all()


def test_dp_features_share_physical_channels_and_preserve_masks_categories(dataset):
    add_commands(dataset)
    # Make wrench channels vary so their learned transform is not identity.
    for directory, _ in dataset.episodes:
        for name, ticks in (('observations', 'observation_ticks'), ('action_observations', 'action_ticks')):
            values = np.load(directory / f'{name}.npy')
            times = np.load(directory / f'{ticks}.npy')
            values[:, dataset.fields['compensated_wrench']] = times[:, None] * .01 + np.arange(6)
            np.save(directory / f'{name}.npy', values)
    raw = dataset[0]
    normalization = fit_dp_limits(dataset)
    assert dataset.normalization is None
    dataset.normalization = normalization
    dataset.cache.clear()
    scaled = dataset[0]
    width = 108
    expected = linear_transform(raw['states'][:, :width], normalization['params_dict']['observation'])
    expected[~raw['state_mask']] = 0
    torch.testing.assert_close(scaled['states'][:, :width], expected, rtol=0, atol=0)
    # The current wrench appears in both state and history, using the same params.
    field = dataset.fields['compensated_wrench']
    torch.testing.assert_close(scaled['states'][-1, field], scaled['history'][-1, :6], rtol=0, atol=0)
    for name in ('phase', 'interaction', 'state_mask', 'history_mask', 'action_mask'):
        torch.testing.assert_close(scaled[name], raw[name], rtol=0, atol=0)
    for name in ('stage', 'interaction', 'execution_status'):
        torch.testing.assert_close(scaled['states'][:, dataset.fields[name]], raw['states'][:, dataset.fields[name]], rtol=0, atol=0)
    assert torch.count_nonzero(scaled['states'][~scaled['state_mask']]) == 0
    assert torch.count_nonzero(scaled['history'][~scaled['history_mask']]) == 0
    assert torch.count_nonzero(scaled['actions'][~scaled['action_mask']]) == 0
    decoded = denormalize_actions(scaled['actions'], normalization)
    torch.testing.assert_close(decoded[raw['action_mask']], raw['actions'][raw['action_mask']], rtol=1e-6, atol=1e-7)
    assert normalization['fit_rows']['action'] == len(dataset)


def test_dp_fit_excludes_invalid_future_padding_and_held_out(dataset):
    add_commands(dataset)
    directory = dataset.episodes[0][0]
    valid = np.load(directory / 'observation_valid.npy')
    valid[1] = False
    np.save(directory / 'observation_valid.npy', valid)
    before = fit_dp_limits(dataset)
    # All rows of a held-out episode are excluded, including extreme values.
    path = episode(dataset.directory, split='validation')
    add_commands(dataset)
    for name in ('actions', 'observations', 'action_observations'):
        values = np.load(path / f'{name}.npy')
        values[:, :6] = 1e6
        np.save(path / f'{name}.npy', values)
    assert fit_dp_limits(dataset) == before
    # Invalid supervision and observation rows never enter fitted statistics.
    values = np.load(directory / 'actions.npy')
    values[7] = 1e6
    np.save(directory / 'actions.npy', values)
    observations = np.load(directory / 'observations.npy')
    observations[[1, -1], :7] = 1e6  # Invalid past frame and unused future frame.
    np.save(directory / 'observations.npy', observations)
    assert fit_dp_limits(dataset) == before
    with pytest.raises(ValueError, match='raw train'):
        fit_dp_limits(ActionWindows(dataset.directory, 'validation'))
    dataset.normalization = before
    with pytest.raises(ValueError, match='raw train'):
        fit_dp_limits(dataset)


def test_dp_fit_includes_start_pose_extension_without_duplicate_horizon_rows(config, dataset, tmp_path):
    add_commands(dataset)
    extension = tmp_path / 'extension'
    extension.mkdir()
    shutil.copyfile(dataset.directory / 'normalization.json', extension / 'normalization.json')
    directory = episode(extension, group='extension')
    manifest_path = directory / 'manifest.json'
    manifest = json.loads(manifest_path.read_text())
    manifest['seed'] = 100
    manifest_path.write_text(json.dumps(manifest))
    extension_reader = ActionWindows(extension, 'train')
    add_commands(extension_reader)
    values = np.load(directory / 'actions.npy')
    values[:, 0] = .3
    np.save(directory / 'actions.npy', values)
    settings = dict(config, dataset=str(dataset.directory))
    combined = TrainingWindows(settings, extension={'dataset': str(extension)})
    normalization = fit_dp_limits(combined)
    rows = np.concatenate([reader[index]['actions'][:1].numpy() for reader in (combined.base, combined.extension)
                           for index in range(len(reader))])
    assert normalization['params_dict']['action'] == fit_linear_limits(rows)
    assert normalization['fit_rows']['action'] == len(combined)
    assert normalization['params_dict']['action']['input_stats']['max'][0] == pytest.approx(.3)
    check_dp_limits(normalization)
    for field, part in (('action', 'scale'), ('observation', 'offset'), ('velocity', 'scale')):
        wrong = copy.deepcopy(normalization)
        wrong['params_dict'][field][part][0] += 1
        with pytest.raises(ValueError, match='normalization'):
            check_dp_limits(wrong)
